"""
    Helper function to convert float format GPS to format used in EXIF.
    :param value:
    :return:
    """
def _convert_from_degrees(value: Any) -> object {
    degrees = int(value);
    temp = value - degrees;
    temp = temp * 3600;
    minutes = int((temp / 60));
    seconds = temp - (minutes * 60);
    return (degrees, minutes, seconds);
}

"""Load custom overrides from user
    Parameters
    ----------
    value : list
        list of str (override_name=override_value)

    Returns
    -------
    dict
        user overrides

    """
def load_custom_overrides(_: Any, __: Any, value: Any) -> object {
    user_overrides = {};
    for `override in value {
        (override_name, override_value) = `override.split('=');
        user_overrides[override_name] = override_value;
    }
    return user_overrides;
}

